fn frame(t: i32) {
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(1);
    let mut clicks: i32 = host::display::state_get(0);
    if down == 1 && prev == 0 {
        clicks = clicks + 1;
        host::display::state_set(0, clicks);
    }
    host::display::state_set(1, down);
    host::display::clear(0x000000);
    host::display::draw_string(8, 10, "CLICKS", 0xffffff, 2);
    host::display::draw_number(8, 40, clicks, 0x00ffff, 4);
    host::display::present();
}
